#include "bits/stdc++.h"

#define rep(i, n) for(int i = 0; i < (n); ++i)
#define all(a) (a).begin(), (a).end()

using namespace std;

using ll = long long;
using vl = vector<ll>;

void solve() {
    int n, k; cin >> n >> k;
    vl a(n);
    rep(i, n) cin >> a[i];
    vl p(n + 1);
    rep(i, n) p[i+1] = p[i] + a[i];
    map<ll, int> cnt;
    rep(i, n + 1) cnt[p[i]]++;
    map<ll, int> cnt2;
    int ans = 0;
    rep(s, n) {
        cnt[p[s]]--;
        int cur = cnt[p[s]];
        if (s) cnt2[p[s]]++;
        cur += cnt2[-p[n]+p[s]];
        if (cur == k) ans++;
    }
    cout << ans << '\n';
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    int t = 1;
    cin >> t;
    while (t--) {
        solve();
    }
    return 0;
}
